WITH filtered AS (SELECT id, store_id, quantity, last_restock, YEAR(last_restock) AS last_restock_year, COALESCE(quantity, 0) AS quantity_filled FROM inventory WHERE last_restock > DATE '2023-08-17'), enriched AS (SELECT e.id, e.store_id, e.last_restock, p.region, p.opened_date FROM filtered e LEFT JOIN stores p ON e.store_id = p.id WHERE p.store_name IS NULL), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY region ORDER BY opened_date DESC NULLS FIRST, id) AS rn FROM enriched QUALIFY rn = 1), filtered_inventory AS (SELECT id, last_restock, region, opened_date, rn, LAST_DAY(opened_date) AS opened_date_month_end, COALESCE(region, 'N/A') AS region_clean FROM ranked WHERE region IS NOT NULL), matched_keys AS (SELECT id FROM filtered_inventory EXCEPT ALL SELECT id FROM inventory WHERE last_restock <= '2023-05-27'), reconciled AS (SELECT s.* FROM filtered_inventory s INNER JOIN matched_keys k ON s.id = k.id) SELECT DATE_TRUNC('YEAR', last_restock) AS year_start, DATE_TRUNC('MONTH', last_restock) AS activity_month, COUNT(*) FILTER (WHERE region = 'Central') AS central_rows, COUNT(*) AS num_rows, COUNT(DISTINCT id) AS distinct_ids, COUNT_IF(region = 'Central') AS central_events, COUNT(DISTINCT id) AS distinct_ids_2, COUNT_IF(region = 'East') AS east_events FROM reconciled GROUP BY year_start, activity_month ORDER BY activity_month DESC NULLS FIRST;
